def a(url,label,cls='button'):
 if not url: return '<span class="coming" role="status">Custom request form coming soon</span>'
 return '<a class="'+cls+'" href="'+url+'"'+(' target="_blank" rel="noopener noreferrer"' if url.startswith('https:') else '')+'>'+label+'</a>'
def card(title,body,link=''):
 return '<article class="card"><h3>'+title+'</h3><p>'+body+'</p>'+link+'</article>'
def choice(url, eyebrow, name, description):
 return '<a class="choice" href="'+url+'"><span class="badge">'+eyebrow+'</span><strong>'+name+'</strong><span>'+description+'</span><b aria-hidden="true">Explore →</b></a>'
def cards(items):return '<div class="grid">'+''.join(items)+'</div>'
