def bundle_card(bundle):
 name=html.escape(bundle['name'])
 items=''.join('<li>'+html.escape(item)+'</li>' for item in bundle['plannedContents'])
 url=BUNDLE_LINKS[bundle['id']]
 live=url.startswith('https://payhip.com/')
 price=('Regular price $' if live else 'Planned regular price $')+bundle['regularPrice']
 action=a(url,'View on Payhip ↗') if live else '<span class="coming" role="status">Payhip link coming soon</span>'
 contents='<details class="bundle-contents"><summary>'+('See bundle contents' if live else 'See planned contents')+'</summary><ul>'+items+'</ul></details>'
 return '<article class="card bundle-card"><span class="badge">'+('Available now' if live else 'In preparation')+'</span><h3>'+name+'</h3><strong class="price">'+price+'</strong>'+contents+'<div class="bundle-action">'+action+'</div></article>'
bundles=hero('Digital product bundles','One collection. More ways to create.','Explore the planned template bundles by theme. Each new bundle will link directly to its Payhip listing when it is published.')
mega=next(bundle for bundle in BUNDLES if bundle['category']=='All Templates')
bundles+=section('Available now','The complete template collection.',cards([bundle_card(mega)]),'light')
groups=[]
for category in dict.fromkeys(bundle['category'] for bundle in BUNDLES if bundle['category']!='All Templates'):
 group=[bundle for bundle in BUNDLES if bundle['category']==category]
 groups.append('<details class="bundle-group"><summary><span>'+html.escape(category)+'</span><small>'+str(len(group))+' bundles</small></summary>'+cards(bundle_card(bundle) for bundle in group)+'</details>')
